WITH matched_keys AS (SELECT order_id FROM shipments EXCEPT ALL SELECT order_id FROM shipments WHERE carrier = 'UPS'), reconciled AS (SELECT s.* FROM shipments s JOIN matched_keys k ON s.order_id = k.order_id) SELECT CASE WHEN cost >= 105 THEN 'HIGH' ELSE 'LOW' END AS cost_tier, DATE_TRUNC('MONTH', delivered_date) AS activity_month, SORT_ARRAY(COLLECT_SET(status)) AS status_list, COUNT(CASE WHEN carrier = 'Kerry' THEN 1 END) AS kerry_count FROM reconciled GROUP BY CASE WHEN cost >= 105 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('MONTH', delivered_date) HAVING COUNT(CASE WHEN carrier = 'Kerry' THEN 1 END) > 1 ORDER BY kerry_count DESC;
